// Mode: Run Once for All Items
// Датасет 145 [E_COM]_partii_и_ostatki -> строки для Supabase

const raw = $('HTTP Request1').first().json.data;

// длинные числовые id (batch_id, sku_id, invoice_id) страхуем от потери точности
const safe = raw.replace(/"(batch_id|sku_id|invoice_id)"\s*:\s*(-?\d{16,})/g, '"$1":"$2"');
const rows = JSON.parse(safe).result[0].data;

if (rows.length === 0) throw new Error('Superset вернул 0 строк');
if (rows.length >= 200000) throw new Error('Упёрлись в row_limit — данные обрезаны');

const txt  = v => (v === undefined || v === '' || v === null ? null : String(v));
const num  = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const dec  = v => { const n = Number(v); return Number.isFinite(n) ? n : null; };
const bool = v => (v === null || v === undefined || v === '' ? null : Boolean(v));
// даты приходят как epoch в миллисекундах
const toDate = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  if (Number.isFinite(n)) return new Date(Math.round(n)).toISOString().slice(0, 10);
  return String(v).slice(0, 10);
};

// Ключ: партия + ячейка. Одна партия может лежать в нескольких ячейках.
// Партии без ячейки ('нет на складе') получают NOCELL.
const acc = new Map();

for (const r of rows) {
  const batchId = txt(r['batch_id']);
  if (!batchId) continue;

  const cellKey = txt(r['cell_key']);
  const key     = `${batchId}|${cellKey ?? 'NOCELL'}`;
  const cur     = acc.get(key);

  if (cur) {
    // страховка: если вдруг придут две строки на одну партию в одной ячейке
    cur.amount         += num(r['amount']);
    cur.amount_pending += num(r['amount_pending']);
    cur.volume_m3       = (cur.volume_m3 ?? 0) + (dec(r['volume_m3']) ?? 0);
    cur.rows_merged    += 1;
    continue;
  }

  acc.set(key, {
    row_key:         key,
    batch_id:        batchId,
    batch_number:    txt(r['batch_number']),
    batch_barcode:   txt(r['batch_barcode']),
    cell_key:        cellKey,
    sku_id:          txt(r['sku_id']),
    sku_title:       txt(r['sku_title']),
    invoice_id:      txt(r['invoice_id']),
    invoice_date:    toDate(r['invoice_date']),
    gtd_number:      txt(r['gtd_number']),
    gtd_kind:        txt(r['gtd_kind']),
    gtd_date:        toDate(r['gtd_date']),
    expiry_date:     toDate(r['expiry_date']),
    is_return:       bool(r['is_return']),
    stock_status:    txt(r['stock_status']),
    zone_title:      txt(r['zone_title']),
    zone_purpose:    txt(r['zone_purpose']),
    zone_stock_type: txt(r['zone_stock_type']),
    amount:          num(r['amount']),
    amount_pending:  num(r['amount_pending']),
    volume_m3:       dec(r['volume_m3']),
    rows_merged:     1,
    query_day:       toDate(r['query_day']),
  });
}

return [{ json: { rows: [...acc.values()] } }];
